package com.andye.warmod.phalanx.client;import com.andye.warmod.phalanx.PhalanxBulletTrajectory;import com.andye.warmod.warhead.client.render.WarheadRenderPipelines;import com.mojang.blaze3d.vertex.*;import java.util.*;import net.fabricmc.fabric.api.client.rendering.v1.level.*;import net.minecraft.client.renderer.state.level.CameraRenderState;import net.minecraft.world.phys.Vec3;
public final class PhalanxTracerRenderer{private record Streak(Vec3 a,Vec3 b){}private record Frame(Vec3 camera,List<Streak> streaks){static final Frame EMPTY=new Frame(Vec3.ZERO,List.of());}private static volatile Frame frame=Frame.EMPTY;private static boolean registered;private PhalanxTracerRenderer(){}public static void register(){if(registered)return;LevelExtractionEvents.END_EXTRACTION.register(PhalanxTracerRenderer::extract);LevelRenderEvents.COLLECT_SUBMITS.register(PhalanxTracerRenderer::render);registered=true;}private static void extract(LevelExtractionContext c){CameraRenderState camera=c.levelState().cameraRenderState;if(c.level()==null||camera==null||camera.pos==null){frame=Frame.EMPTY;return;}double now=c.level().getGameTime()+c.deltaTracker().getGameTimeDeltaPartialTick(true);ArrayList<Streak> out=new ArrayList<>();for(var t:PhalanxTracerManager.snapshot(c.level().getGameTime())){double age=Math.max(0,now-t.startTime());Vec3 b=PhalanxBulletTrajectory.position(t.origin(),t.velocity(),age),a=PhalanxBulletTrajectory.position(t.origin(),t.velocity(),Math.max(0,age-.35));if(a.isFinite()&&b.isFinite())out.add(new Streak(a,b));}frame=new Frame(camera.pos,List.copyOf(out));}private static void render(LevelRenderContext c){Frame f=frame;if(f==Frame.EMPTY||c.poseStack()==null)return;for(var s:f.streaks){PoseStack stack=c.poseStack();stack.pushPose();Vec3 r=s.a.subtract(f.camera);stack.translate(r.x,r.y,r.z);Vec3 d=s.b.subtract(s.a);c.submitNodeCollector().submitCustomGeometry(stack,WarheadRenderPipelines.NUCLEAR_FLASH,(p,b)->quad(p,b,d));stack.popPose();}}private static void quad(PoseStack.Pose p,VertexConsumer b,Vec3 d){Vec3 side=d.cross(new Vec3(0,1,0));if(side.lengthSqr()<1E-8)side=new Vec3(.02,0,0);else side=side.normalize().scale(.025);v(p,b,side,255,245,180,250);v(p,b,side.scale(-1),255,245,180,250);v(p,b,d.subtract(side),255,126,25,35);v(p,b,d.add(side),255,126,25,35);}private static void v(PoseStack.Pose p,VertexConsumer b,Vec3 v,int r,int g,int bl,int a){b.addVertex(p,(float)v.x,(float)v.y,(float)v.z).setColor(r,g,bl,a).setUv(0,0).setOverlay(0).setLight(0xF000F0).setNormal(p,0,1,0);}}
